const mcpParityPageHead = `# How much of the web app an agent can do

<!-- Generated by backend/gates/mcpparity_test.go. Do not edit by hand. -->

`

const mcpParityStates = `## What each state means

| State | Meaning |
|---|---|
| Open | The operation carries ` + "`x-mcp-tool`" + `, so a user's agent can run it through MCP, with that user's grants. |
| Ask first | Open, and its tool tells the agent to ask its user first (` + "`ask_user_first`" + `). A legal or lasting act stays open this way. |
| Pending | Closed for now. Nothing keeps it closed but the work of opening it. |
| Security | Closed for good: a secret, more rights than the user gave, or a rule the whole company runs on. |
| Covered | Closed as a route, because another tool does the same job. |
| Sign-in | A step of signing in or out, which an agent has no use for. |

The contract says which state applies: ` + "`x-mcp-tool`" + `, or ` + "`x-agent-access`" + ` with ` + "`x-human-only-reason`" + ` in
` + "`backend/api/crm.yaml`" + `. [an-agent-does-what-its-user-does.md](../principles/an-agent-does-what-its-user-does.md)
says what keeps an action closed. A user's role narrows both doors the same way, so these counts do not change by role.
[mcp-tool-roles.md](mcp-tool-roles.md) shows what each role can do.

`

const mcpParityMethod = `## How an operation gets its group

1. An operation no signed-in user's cookie admits is public. This is the rule
   ` + "`tools/gen-agentpolicy`" + ` holds a human-only operation to.
2. A path rule places it, or the default of its first OpenAPI tag. The table is in
   ` + "`backend/gates/mcpparityplaces_test.go`" + `. A tag that spans groups, such as ` + "`Identity`" + `, has no default, so a
   new route under it fails the gate until someone places it. So does a new tag.
3. A settings area splits by what the seeded ` + "`rep`" + ` role may do. A setting it passes goes to the non-admin group,
   and the rest go to the admin group. So one area can have its reads in the first group and its writes in the second.

The answer for ` + "`rep`" + ` comes from these places, in this order:

- ` + "`decided_by: measured`" + `: [mcp-tool-roles.json](mcp-tool-roles.json) ran the real tool on that role. Only a verb that
  serves one operation counts, because a row for a shared verb says nothing about any one route. ` + "`refused_by`" + ` is then the
  first grant in the sweep's tool checks table that the rep lacks, or every alternative of a check the rep holds none of.
  A row-scope check is no grant, so it is never named there.
- ` + "`decided_by: grant_checks`" + `: for an operation no swept verb serves alone, the checks the handler makes, against
  [rbac-matrix.md](rbac-matrix.md). The gate walks from
  the method ` + "`compose.Server`" + ` serves the operation with, and follows ` + "`auth.Require`" + `, ` + "`auth.RequireAny`" + `,
  ` + "`auth.RequireAdmin`" + ` and ` + "`auth.RequireCoach`" + `. A boolean read such as ` + "`auth.Allows`" + ` or ` + "`auth.ReadGranted`" + `
  refuses nobody by itself, so it counts as conditional.
- ` + "`decided_by: no_check`" + `: the walk found no check, so any member passes.
- ` + "`decided_by: declared`" + `: ` + "`x-settings-audience`" + ` in the contract, on an operation where the source cannot answer: its
  object is known only at run time, or a branch decides who a check stops. The gate fails a declaration the source could
  answer, and a missing one where it cannot.

Each operation's group, area, state and how it was decided are in [mcp-parity.json](mcp-parity.json).

The same test writes ` + "`backend/internal/platform/workarea/workareas.json`" + `, which the server reads to hold a passport to the
areas its user chose. Each of the first six groups is one area a user can turn on or off. The other three are reached only
by a passport set to all areas.

`

const mcpParityMisses = `## What a scan of the web app can miss

The scan reads ` + "`frontend/src`" + ` and each unit's ` + "`frontend`" + ` folder. It leaves out tests and stories. It finds a typed
call such as ` + "`api.GET(\"/path\")`" + `, a path held in a constant or a template in the same file and passed to the client, and a
` + "`/v1/`" + ` URL used as a link, an image or an upload.

It cannot see these, so the web app's real count may be higher:

- a URL the server sends back, such as a company's ` + "`logo_url`" + `;
- a URL built from a variable that holds the ` + "`/v1`" + ` part;
- a path passed in from another file, listed under ` + "`computed_calls_no_path_was_found_for`" + ` in the JSON.

It can also count too much: finding a call says the code can make it, and a screen may be hidden behind a feature or
a role. Routes a unit adds under ` + "`/ext/`" + ` are outside the contract, so they are counted apart.

`

const mcpParityRegenerate = `## Regenerate

The gate fails when these files and their sources disagree, in either direction. From ` + "`backend/`" + `:

    ` + mcpParityCommand + `
`

func renderMCPParityPage(report parityReport) []byte {
	var b bytes.Buffer
	b.WriteString(mcpParityPageHead)
	renderParityHeadline(&b, report)
	b.WriteString(mcpParityStates)
	renderParityGroupSummary(&b, report)
	for _, group := range report.Groups {
		renderParityGroup(&b, group)
	}
	b.WriteString(mcpParityMethod)
	b.WriteString(mcpParityMisses)
	b.WriteString(mcpParityRegenerate)
	return b.Bytes()
}

func renderParityHeadline(b *bytes.Buffer, report parityReport) {
	signed := report.Headline.SignedIn
	fmt.Fprintf(b, "**%s** of what the web app calls for a signed-in user is open to that user's agent through MCP: %d of %d operations.\n",
		percentText(signed.WebParity), signed.WebOpen, signed.WebCalls)
	fmt.Fprintf(b, "Counting what another tool covers, it is %s. Once every pending operation opens, it is %s. What is left is closed for security, apart from signing out.\n\n",
		percentText(report.Headline.WebParityWithCovered), percentText(report.Headline.WebParityOncePending))
	b.WriteString("## The three counts\n\n")
	b.WriteString("| Counted over | Operations | Open to an agent | Parity |\n|---|---:|---:|---:|\n")
	fmt.Fprintf(b, "| Every operation in the contract | %d | %d | %s |\n", report.Headline.AllOperations, signed.Open, percentText(percentOf(signed.Open, report.Headline.AllOperations)))
	fmt.Fprintf(b, "| Operations a signed-in user reaches | %d | %d | %s |\n", signed.Operations, signed.Open, percentText(signed.Parity))
	fmt.Fprintf(b, "| Operations the web app calls for a signed-in user | %d | %d | %s |\n\n", signed.WebCalls, signed.WebOpen, percentText(signed.WebParity))
	b.WriteString("The last count answers the question of parity with the web app, so it leads this page. The first adds pages for " +
		"visitors with no account, where no agent acts because no signed-in user does. ")
	fmt.Fprintf(b, "The second adds routes where the scan found no web app call: %d of those are open, so an agent can do them.\n\n",
		report.Headline.OpenWithNoWebCallFound)
	b.WriteString("| Of the operations the web app calls | Count |\n|---|---:|\n")
	fmt.Fprintf(b, "| Open, and the agent does not ask first | %d |\n| Open, and the agent asks first | %d |\n| Pending | %d |\n| Covered by another tool | %d |\n| Closed for security | %d |\n| Sign-in | %d |\n\n",
		signed.WebOpen-signed.WebAskFirst, signed.WebAskFirst, signed.WebPending, signed.WebCovered, signed.WebSecurity,
		signed.WebCalls-signed.WebOpen-signed.WebPending-signed.WebCovered-signed.WebSecurity)
}

func renderParityGroupSummary(b *bytes.Buffer, report parityReport) {
	b.WriteString("## The groups\n\nEach operation is in one group. Ask first is a part of Open, so leave it out of a sum. The other state " +
		"columns can then add up to less than a row's operations, for two reasons. The operations in the public group are in no state an " +
		"agent has, and the sign-out step is under Password, sessions and second factor.\n\n")
	b.WriteString("| Group | Operations | Open | Ask first | Pending | Security | Covered | Web app calls | Parity (web app) | Parity (signed-in) |\n")
	b.WriteString("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n")
	for _, group := range report.Groups {
		fmt.Fprintf(b, "| [%s](#%s) | %s |\n", group.Title, markdownAnchor(group.Title), parityRowCells(group.parityCounts, group.Key))
	}
	b.WriteString("\n")
}

func renderParityGroup(b *bytes.Buffer, group parityGroupRow) {
	fmt.Fprintf(b, "## %s\n\n%s\n\n", group.Title, group.What)
	b.WriteString("| Area | Operations | Open | Ask first | Pending | Security | Covered | Web app calls | Parity (web app) | Parity (signed-in) |\n")
	b.WriteString("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n")
	for _, area := range group.Areas {
		fmt.Fprintf(b, "| %s | %s |\n", area.Title, parityRowCells(area.parityCounts, group.Key))
	}
	b.WriteString("\n")
}

// parityRowCells prints one row's counts. The public group has no parity to
// state, because no signed-in user reaches it.
func parityRowCells(counts parityCounts, group string) string {
	webParity, signedParity := percentText(counts.WebParity), percentText(counts.Parity)
	if group == groupPublic {
		webParity, signedParity = "n/a", "n/a"
	} else if counts.WebCalls == 0 {
		webParity = "n/a"
	}
	return fmt.Sprintf("%d | %d | %d | %d | %d | %d | %d | %s | %s",
		counts.Operations, counts.Open, counts.AskFirst, counts.Pending, counts.Security, counts.Covered, counts.WebCalls, webParity, signedParity)
}

func percentText(value float64) string { return fmt.Sprintf("%.1f%%", value) }

// markdownAnchor is the fragment a heading gets: lower case, punctuation gone and
// spaces as hyphens.
func markdownAnchor(title string) string {
	var out strings.Builder
	for _, r := range strings.ToLower(title) {
		switch {
		case r >= 'a' && r <= 'z', r >= '0' && r <= '9', r == '-':
			out.WriteRune(r)
		case r == ' ':
			out.WriteRune('-')
		}
	}
	return out.String()
}
